            writer.WriteString("tenantId", mailWebhookDelivery.TenantId);

            writer.WriteString("updatedAt", mailWebhookDelivery.UpdatedAt.ToString(UpdatedAtFormat));

            writer.WriteNumber("version", mailWebhookDelivery.VarVersion);

            if (mailWebhookDelivery.DeadLetteredAtOption.IsSet)
