            if (mailWebhookDelivery.SucceededAtOption.IsSet)
                writer.WriteString("succeededAt", mailWebhookDelivery.SucceededAtOption.Value!.Value.ToString(SucceededAtFormat));

            foreach (var property in mailWebhookDelivery.AdditionalProperties)
            {
                if (property.Key == "attemptCount" || property.Key == "createdAt" || property.Key == "deduplicationKey" || property.Key == "event" || property.Key == "id" || property.Key == "nextAttemptAt" || property.Key == "status" || property.Key == "subscriptionId" || property.Key == "tenantId" || property.Key == "updatedAt" || property.Key == "version" || property.Key == "deadLetteredAt" || property.Key == "lastErrorCode" || property.Key == "lastErrorMessage" || property.Key == "leaseExpiresAt" || property.Key == "leaseOwner" || property.Key == "replayOf" || property.Key == "responseStatus" || property.Key == "succeededAt") throw new JsonException("Additional properties cannot override declared properties");
                writer.WritePropertyName(property.Key);
